const GUIDA_SPECIE = [{"id":"19_species_aesculus_hippocastanum","nomeSci":"Aesculus hippocastanum","famiglia":"Ippocastanaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa centrale, caucaso","varieta":null,"isVarieta":false,"pagina":19,"note":"Ramo a \"S\" Corteccia a squame Sulla punta del ramo un'enorme gemma a fiore lucida ed appiccicosa. ( in inverno). Foglia composta, digitata. Fiorisce ad aprile/maggio con un fiore bianco Frutto, riccio con castagne. Sta scomparendo a causa della CAMERARIA, insetto arrivato dall'America","gemmeTipologia":"a fiore","fogliaTipo":"composta","fogliaComposta":"digitata"},{"id":"20_species_aesculus_x","nomeSci":"Aesculus x","famiglia":"Ippocastanaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa centrale, caucaso","varieta":null,"isVarieta":false,"pagina":20,"note":"IBRIDO: Aesculus hippocastanum + Aesculus pavia Identico nelle sue caratteristiche ai genitori ma più piccolo e con fiore di colore rosa. Foglia composta , digitata, con lamina fortemente stropicciata ; ma aesculus x pavia ha una forma più ellittica/ovale regolare; hippocastanum invece ha un aumento della superficie fogliare nella parte terminale. Le gemme non sono lucide ed appiccicose. Il riccio che avvolge la castagna è quasi privo di spine. Corteccia non a squame","fogliaTipo":"composta","fogliaComposta":"digitata","fogliaLamina":"ellittica"},{"id":"21_species_liriodendron_tulipifera","nomeSci":"Liriodendron tulipifera","famiglia":"Magnoliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"america nord orientale","varieta":null,"isVarieta":false,"pagina":21,"note":"Rami che formano un arco partendo dal fusto. Frutto particolare sugli apici e sulle ali , di facile riconoscimento invernale. Foglia palmata, tronca all'apice. Gemma a fiore apicale molto grossa e foglia particolarissima, tronca senza punta. Fioritura nel mese di maggio, il cui fiore somiglia ad un tulipano ( tulipifera)","gemmePosizione":"apicale","gemmeTipologia":"a fiore","fogliaLamina":"palmata","fogliaApice":"tronca"},{"id":"22_species_magnolia_grandiflora","nomeSci":"Magnolia grandiflora","famiglia":"Magnoliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"sempreverde","grandezza":"2","provenienza":"stati uniti","varieta":null,"isVarieta":false,"pagina":22,"note":"Foglia ovale grande, coriacea di difficilissima degradazione. Rami basali che, se appoggiati al terreno, emettono altri rami. Grande chioma compatta. Fiorisce con un fiore bianco immenso. Frutto enorme di facile riconoscimento"},{"id":"23_variety_magnolia_grandiflora","nomeSci":"Magnolia grandiflora","famiglia":"Magnoliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"sempreverde","grandezza":"2","provenienza":"stati uniti","varieta":"Gallisoniensis","isVarieta":true,"pagina":23,"note":"VARIETA' CON PAGINA INFERIORE SCURA"},{"id":"24_variety_magnolia_g","nomeSci":"Magnolia g.","famiglia":"Magnoliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"stati uniti","varieta":"Liliflora","isVarieta":true,"pagina":24,"note":"VARIETA' CADUCIFOLIA SENZA FOGLIA CORIACEA"},{"id":"25_species_betula_pendula","nomeSci":"Betula pendula","famiglia":"Betulaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":25,"note":"Rami secondari che scendono verso il basso. Tronco da non confondere con quello del pioppo, i cui rami tendono verso l'alto. Soffre siccità e non tollera potature drastiche. Foglia ellittica, triangolare, a punta lunga e glabra, con margine doppiamente dentato. Corteccia giovane di colore bianchissimo, scurisce col tempo ma con parti giovani sempre bianchissime","fogliaLamina":"ellittica","fogliaMargine":"dentato"},{"id":"26_species_betula_papyrifera","nomeSci":"Betula papyrifera","famiglia":"Betulaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"nord america","varieta":null,"isVarieta":false,"pagina":26,"note":"Tronco avvolto da una corteccia che si spoglia quasi a papiro. Bianco dei fusti ancor più accentuato, più resistente al caldo. Foglia alterna, ovale, con margine doppiamente seghettato","fogliaMargine":"seghettato"},{"id":"28_species_platanus_occidentalis","nomeSci":"Platanus occidentalis","famiglia":"Platanaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"america","varieta":null,"isVarieta":false,"pagina":28,"note":"Corteccia a placche chiare. Rami alterni e frutti globosi Foglia palmata con PICCIOLO CORTO , a lobi più o meno profondamente incisi","ramiInserzione":"alterni","fogliaLamina":"palmata"},{"id":"29_species_platanus_x","nomeSci":"Platanus x","famiglia":"Platanaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"america del nord","varieta":null,"isVarieta":false,"pagina":29,"note":"IBRIDO: Platanus occidentalisi + Platanus orientalis Corteccia a placche grosse e chiare. Frutti a gruppi di due o quattro. Foglia palmata con punte dei lobi molto accentuate: grande variabilità di forma anche sullo stesso individuo","fogliaLamina":"palmata"},{"id":"30_species_platanus_orientalis","nomeSci":"Platanus orientalis","famiglia":"Platanaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa m. - asia occident.","varieta":null,"isVarieta":false,"pagina":30,"note":"Frutti a gruppi di tre o sei, portati da lungo peduncolo. Corteccia a placche piccolissime. Foglia palmata con lobo centrale inciso molto profondamente e con lati paralleli","fogliaLamina":"palmata"},{"id":"34_species_acer_platanoides","nomeSci":"Acer platanoides","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":34,"note":"Corteccia liscia da giovane, col tempo fessurata a rombi. Foglia palmata, lobi accentuati e punte molto lunghe. Picciolo molto lungo. Frutto disamara a 180°","fogliaLamina":"palmata"},{"id":"35_variety_acer_platanoides","nomeSci":"Acer platanoides","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":"Globosum","isVarieta":true,"pagina":35,"note":"Chioma globosa Foglia palmata, lobi accentuati e punte molto lunghe. Nervature giallastre. Frutto disamara a 180°","chiomaForma":"globosa","fogliaLamina":"palmata"},{"id":"36_variety_acer_platanoides","nomeSci":"Acer platanoides","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":"Drummondii","isVarieta":true,"pagina":36,"note":"Foglia variegata di colore BIANCO Foglia palmata, lobi accentuati e punte molto lunghe. Frutto disamara a 180°","fogliaLamina":"palmata"},{"id":"37_variety_acer_platanoides","nomeSci":"Acer platanoides","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":"Crimson King","isVarieta":true,"pagina":37,"note":"Foglia variegata di colore ROSSO PORPORA Foglia palmata, lobi accentuati e punte molto lunghe. Frutto disamara a 180°","fogliaLamina":"palmata"},{"id":"38_species_acer_pseudoplatanus","nomeSci":"Acer pseudoplatanus","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa, acero montano","varieta":null,"isVarieta":false,"pagina":38,"note":"Corteccia a piccole squame negli adulti. Gemma centrale, ovale di colore verde chiaro. Foglia palmata, lobi SEGHETTATI, meno accentuati del platanoides, con punte più corte. Picciolo molto lungo. Frutto disamara a 45°","fogliaLamina":"palmata"},{"id":"39_variety_acer_pseudoplatanus","nomeSci":"Acer pseudoplatanus","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa, acero montano","varieta":"Atropurpureum","isVarieta":true,"pagina":39,"note":"Pagina inferiore della foglia di colore ROSSO PORPORA. Corteccia a piccole squame negli adulti. Gemma centrale, ovale di colore verde chiaro. Foglia palmata, lobi SEGHETTATI, meno accentuati del platanoides, con punte più corte. Picciolo molto lungo. Frutto disamara a 45°","fogliaLamina":"palmata"},{"id":"40_species_acer_campestre","nomeSci":"Acer campestre","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"europa,","varieta":null,"isVarieta":false,"pagina":40,"note":"Corteccia a CUBETTO, screpolata di colore grigio/bruno. Gemma centrale, ovale di colore verde chiaro. Foglia palmata, a 5 lobi, con margine liscio. Punte arrotondate. Picciolo molto lungo. Frutto disamara a 180°. Utilizzato per la formazione di siepi","fogliaLamina":"palmata"},{"id":"41_species_acer_negundo","nomeSci":"Acer negundo","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"nord america","varieta":null,"isVarieta":false,"pagina":41,"note":"Corteccia grigio/bruna, liscia da giovane e fessurata da adulto.. Rami giovani di colore verde chiaro. Foglia COMPOSTA IMPARIPENNATA, con 3/5 foglioline dentate irregolarmente; fogliolina centrale con forma variabile, spesso trilobata D'inverno la parte giovane dell'anno è ricoperta dalla pruina cerosa, patina bianca. Gemme opposte e rami opposti. Picciolo molto lungo. Frutto disamara ad angolo ACUTO, in GRAPPOLI PERSISTENTI, anche in inverno. PIANTA DIOICA","ramiInserzione":"opposti","fogliaTipo":"composta","fogliaComposta":"imparipennata"},{"id":"42_variety_acer_negundo","nomeSci":"Acer negundo","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"nord america","varieta":"Argenteovariegatum","isVarieta":true,"pagina":42,"note":"FOGLIA VARIEGATA BIANCA,"},{"id":"43_variety_acer_negundo","nomeSci":"Acer negundo","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"nord america","varieta":"Flamingo","isVarieta":true,"pagina":43,"note":"FOGLIA VARIEGATA BIANCO- ROSATO"},{"id":"44_variety_acer_negundo","nomeSci":"Acer negundo","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"nord america","varieta":"Aureovariegatum","isVarieta":true,"pagina":44,"note":"FOGLIA VARIEGATA GIALLO"},{"id":"45_species_acer_saccharinum","nomeSci":"Acer saccharinum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"nord america","varieta":null,"isVarieta":false,"pagina":45,"note":"Da non confondere con l'acer Saccharum ( Acero canadese). Corteccia grigia, liscia da giovane poi a scaglie da anziana (50 anni almeno) Rami giovani lunghi e spesso pendenti Foglia PALMATA SEGHETTATA, PROFONDAMENTE INCISA, con pagina inferiore colore BIANCO (ZUCCHERO), causa presenza di peli bianchi. Frutto disamara a grappoli con angolo 30°","fogliaLamina":"palmata"},{"id":"46_variety_acer_saccharinum","nomeSci":"Acer saccharinum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"nord america","varieta":"Laciniatum Wieri","isVarieta":true,"pagina":46,"note":"FOGLIA CON LOBI LANCINATI, FORTEMENTE INCISI, SIMILE ALLA FOGLIA D'ACERO GIAPPONESE. PAGINA INFERIORE ARGENTEA"},{"id":"47_species_acer_rubrum","nomeSci":"Acer rubrum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"nord america","varieta":null,"isVarieta":false,"pagina":47,"note":"GEMME ROSSASTRE Rosso vivo in fioritura, in estate verde e rosso vivo in autunno Foglia con 3-5 lobi, margine dentato, confondibile con Acer platanoides ma ha pagina inferiore chiara Disamare di colorazione rossastra","fogliaMargine":"dentato"},{"id":"48_variety_acer_rubrum","nomeSci":"Acer rubrum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"nord america","varieta":"October Glory","isVarieta":true,"pagina":48,"note":"COLORE AUTUNNALE DELLE FOGLIE DI UN ROSSO INTENSISSIMO Foglia con 3-5 lobi, margine dentato, confondibile con Acer platanoides ma ha pagina inferiore chiara Disamare di colorazione rossastra","fogliaMargine":"dentato"},{"id":"49_species_acer_japonicum","nomeSci":"Acer japonicum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"giappone","varieta":null,"isVarieta":false,"pagina":49,"note":"Rami opposti, sottili da giovani. Foglia con 7-11 lobi, poco incisi, fino a metà o meno. Picciolo coperto da fitta peluria. Disamare con ali espanse","ramiInserzione":"opposti"},{"id":"50_species_acer_palmatum","nomeSci":"Acer palmatum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone, corea, cina","varieta":null,"isVarieta":false,"pagina":50,"note":"Rami opposti, sottili da giovani. Portamento eretto o con chioma ampia, in alcuni casi anche ad ombrello Foglia con 5-7 lobi, profondi e con apici appuntiti, Picciolo sempre glabro. Ciuffi di peli alle ascelle delle nervature. Disamare ad angolo ottuso","chiomaForma":"ad ombrello","ramiInserzione":"opposti"},{"id":"51_variety_acer_palmatum","nomeSci":"Acer palmatum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone, corea, cina","varieta":"Dissectum","isVarieta":true,"pagina":51,"note":"INCISIONE DELLE FOGLIE PROFONDISSIMA, TANTO DA ASSOMIGLIARE AD UN SACCHARINUM COLORE VERDE !!! Foglia con 5-7 lobi, profondi e con apici appuntiti, Picciolo sempre glabro. Ciuffi di peli alle ascelle delle nervature. Disamare ad angolo ottuso"},{"id":"52_variety_acer_palmatum","nomeSci":"Acer palmatum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone, corea, cina","varieta":"Dissectum Atropurpureum","isVarieta":true,"pagina":52,"note":"INCISIONE DELLE FOGLIE PROFONDISSIMA, TANTO DA ASSOMIGLIARE AD UN SACCHARINUM COLORE ROSSO FUOCO!!! Foglia con 5-7 lobi, profondi e con apici appuntiti, Picciolo sempre glabro. Ciuffi di peli alle ascelle delle nervature. Disamare ad angolo ottuso"},{"id":"53_variety_acer_palmatum","nomeSci":"Acer palmatum","famiglia":"Aceraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone, corea, cina","varieta":"Reticulatum","isVarieta":true,"pagina":53,"note":"INCISIONE DELLE FOGLIE PROFONDISSIMA, TANTO DA ASSOMIGLIARE AD UN SACCHARINUM NERVATURE DELLE FOGLIE DI COLORE VERDE MOLTO PIU' SCURO DELLA PAGINA FOGLIARE ! Foglia con 5-7 lobi, profondi e con apici appuntiti, Picciolo sempre glabro. Ciuffi di peli alle ascelle delle nervature. Disamare ad angolo ottuso"},{"id":"54_species_fagus_sylvatica","nomeSci":"Fagus sylvatica","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":54,"note":"Insieme al platano è da considerarsi albero totem, superando abbondantemente i 20 metri. Portamento dei rami assurgente (verticale). Corteccia grigia e liscia, con piaghe che ricordano pelle di elefante. Presenta però grosse ramificazioni verticali formando una CORTECCIA INCLUSA . GEMME APICALI, ALTERNE LUNGHE ED APPUNTITE. Foglie ovali a margine ondulato, coperte da fitta peluria che tende a scomparire in estate Frutto noce coperto da involucro","ramiForma":"assurgente","fogliaMargine":"ondulato"},{"id":"55_variety_fagus_sylvatica","nomeSci":"Fagus sylvatica","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":"Pendula","isVarieta":true,"pagina":55,"note":"PORTAMENTO DEI RAMI PENDULO. Le ramificazioni principali , crescendo negli anni, vengono esposte al sole e fessurano la corteccia Foglie ovali a margine ondulato, coperte da fitta peluria che tende a scomparire in estate Frutto noce coperto da involucro","fogliaMargine":"ondulato"},{"id":"56_variety_fagus_sylvatica","nomeSci":"Fagus sylvatica","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":"Atropurpureum","isVarieta":true,"pagina":56,"note":"FOGLIE ROSSO PORPORA !!! Foglie ovali a margine ondulato, coperte da fitta peluria che tende a scomparire in estate Frutto noce coperto da involucro","fogliaMargine":"ondulato"},{"id":"57_variety_fagus_sylvatica","nomeSci":"Fagus sylvatica","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":"Tricolor","isVarieta":true,"pagina":57,"note":"FOGLIE MARGINATE BIANCO ROSATO !!! Foglie ovali a margine ondulato, coperte da fitta peluria che tende a scomparire in estate Frutto noce coperto da involucro","fogliaMargine":"ondulato"},{"id":"58_variety_fagus_sylvatica","nomeSci":"Fagus sylvatica","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":"Asplenifolia","isVarieta":true,"pagina":58,"note":"FOGLIE A MARGINE FINEMENTE LOBATO !!! Frutto noce coperto da involucro"},{"id":"59_species_quercus_robur","nomeSci":"Quercus robur","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":59,"note":"Pianta maestosa, si adatta più ai climi del nord. Esiste in natura in contesto boschivo Corteccia molto incisa rugosa. Foglia lobata con bordi arrotondati, a differenza delle americane con punte . Nella parte iniziale molto stretta per poi allargarsi sul finale ( a differenza del rovere che ha la parte centrale più larga). Picciolo cortissimo quasi inesistente, foglia sub-sessile. Base fogliare con ricciolo, chiamato orecchietta Ghiande allungate e cupola avvolgente","fogliaLamina":"lobata"},{"id":"60_variety_quercus_robur","nomeSci":"Quercus robur","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa","varieta":"Fastigiata","isVarieta":true,"pagina":60,"note":"RAMI CHE TENDONO TUTTI VERSO LA PUNTA IDEM TUTTE LE ALTRE CARATTERISTICHE","chiomaForma":"fastigiata"},{"id":"61_species_quercus_rubra","nomeSci":"Quercus rubra","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"nord america","varieta":null,"isVarieta":false,"pagina":61,"note":"Pianta maestosa, a crescita molto veloce ma con serie di problematiche derivate da attaccata da funghi cariogeni (ganoderma) Foglia rossastra, più in primavera ,in autunno tende al marrone, grande, lobata APPUNTITA, con 1-3 denti. Produce quantità esorbitante di ghiande quindi di alta percentuale riproduttiva. Ghianda conosciutissima più schiacciata e tonda, e cupola a basketto","fogliaLamina":"lobata"},{"id":"62_species_quercus_palustris","nomeSci":"Quercus palustris","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"nord america","varieta":null,"isVarieta":false,"pagina":62,"note":"Pianta maestosa, dal colore rosso vivo in autunno, in primavera ed estate verdi. Predilige terreni umidi ma si adatta bene anche alle nostre latitudini. Foglia lobata a punta ma lobi profondamente incisi, all'interno dalla nervatura centrale Ghiande ancora più schiacciate a forma di trottola Fusto rugoso , crescita veloce come la rubra","fogliaLamina":"lobata"},{"id":"63_variety_quercus_ilex","nomeSci":"Quercus ilex","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"sempreverde","grandezza":"2","provenienza":"europa meridionale","varieta":null,"isVarieta":true,"pagina":63,"note":"ATTENZIONE, E' UN SEMPREVERDE !!! Chioma piatta e compatta Foglia lanceolata coriacea piccola con lobi spinosi e nervatura centrale lineare. Fitta peluria grigia su pagina inferiore. Ghianda ovale con cupola a squame appressate","chiomaForma":"piatta e compatta","gemmeOrientamento":"appressate","fogliaTipo":"semplice","fogliaLamina":"lanceolata"},{"id":"64_variety_quercus_suber","nomeSci":"Quercus suber","famiglia":"Fagaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"sempreverde","grandezza":"2","provenienza":"europa meridionale","varieta":null,"isVarieta":true,"pagina":64,"note":"ATTENZIONE, E' UN SEMPREVERDE !!! Chioma aperta. Foglia lobata coriacea piccola, molto simile al leccio ma con NERVATURA CENTRALE SINUOSA. CORTECCIA RUGOSA E SPESSA, spugnosa, chiara. Ghianda ovale con cupola a squame DIVERGENTI","gemmeOrientamento":"divergenti","fogliaTipo":"semplice","fogliaLamina":"lobata"},{"id":"65_species_laurus_nobilis","nomeSci":"Laurus nobilis","famiglia":"Lauraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"sempreverde","grandezza":"2","provenienza":"europa meridionale","varieta":null,"isVarieta":false,"pagina":65,"note":"SEMPREVERDE ! PIANTA DIOICA !!! Foglia ellittica coriacea a bordo ondulato. PROFUMO AROMATICO QUANDO STROPICCIATA., di colore verde scuro sulla pagina superiore, mentre pallida ed opaca sulla pagina inferiore. Pianta dioica con fiori femminili giallo-verdastri in glomeruli all'ascella delle foglie, ad inizio primavera. Bacche violacee in autunno","fogliaLamina":"ellittica","fogliaMargine":"ondulato"},{"id":"66_species_tilia_cordata","nomeSci":"Tilia cordata","famiglia":"Malvaceae - Ex Tiliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa centrale","varieta":null,"isVarieta":false,"pagina":66,"note":"Veloce crescita, con legno debolissimo; spesso capitozzata Corteccia striata parallelamente Problema afidi con alta produzione melata Foglia a cuore, cordata, con margine seghettato; Più piccola delle altre specie; gemme con PERULA, foglia gobbata che la ricopre. Fioritura a giugno, profumatissima, sopra le foglie Frutto (carcerulo) portato da un peduncolo , ( foglia modificata) Nel cordata frutto liscio e tondo","fogliaLamina":"cordata","fogliaMargine":"seghettato","fogliaBase":"cordata"},{"id":"67_species_tilia_platyphyllos","nomeSci":"Tilia platyphyllos","famiglia":"Malvaceae - Ex Tiliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa centrale e merid.","varieta":null,"isVarieta":false,"pagina":67,"note":"CARATTERISTICA FOGLIA GRANDE ! Caratteristica foglie identica al cordata ma più grande. Corteccia generalmente romboide ma di difficile Riconoscimento. Foglia a cuore, cordata, con margine seghettato; FIORITURA SOTTO LE FOGLIE !!! Ciuffi di peli sotto la foglia INESISTENTE Al tatto, peluria se presente, diffusa ovunque Frutto CARCERULO allungato con costolature","fogliaLamina":"cordata","fogliaMargine":"seghettato","fogliaBase":"cordata"},{"id":"68_species_tilia_x","nomeSci":"Tilia x","famiglia":"Malvaceae - Ex Tiliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":68,"note":"IBRIDO IBRIDO NATURALE Tilia cordata + Tilia platyphyllos CARATTERISTICO TRONCO CON MOLTE GOBBE E RICACCI Foglia a cuore, cordata, con margine seghettato; FIORITURA SOTTO LE FOGLIE !!! Ciuffi di peli bianchi nelle ascelle delle nervature Frutto CARCERULO OVOIDALE, LEGGERMENTE COSTOLUTO","gemmeForma":"ovoidale","fogliaLamina":"cordata","fogliaMargine":"seghettato","fogliaBase":"cordata"},{"id":"69_variety_tilia_tomentosa","nomeSci":"Tilia tomentosa","famiglia":"Malvaceae - Ex Tiliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa meridionale","varieta":null,"isVarieta":true,"pagina":69,"note":"Corteccia striata, con incisioni poco profonde. GIOVANI RAMI VERDI COPERTI DA TOMENTOSITA' (pelosità). Foglia TOMENTOSA, BIANCA NELLA PAGINA INFERIORE, vellutata, presente anche sulla PARTE GIOVANE DEL RAMO BIANCO GRIGIASTRO. TOMENTOSITA' presente anche sulla parte inferiore del carcerulo Anche le gemme sono TOMENTOSE Frutto liscio e bianco, sotto la foglia"},{"id":"70_species_fraxinus_excelsior","nomeSci":"Fraxinus excelsior","famiglia":"Oleaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"autoctona - europa","varieta":null,"isVarieta":false,"pagina":70,"note":"Foglia imparipennata Legno consistente ma non eccessivamente duro. Corteccia non molto significativa, confondibile con acero Platanoide. Elemento principe di riconoscimento sono le gemme, TUTTE NERE E QUELLA APICALE A FORMA DI ZOCCOLO DI CAPRA. Grappoli di samare singole. Foglia composta, imparipennata, foglioline laterali attaccate direttamente al rachide senza peduncolo. Fiorisce con fiore di poco rilievo, mentre gemma","gemmePosizione":"apicale","fogliaTipo":"composta","fogliaComposta":"imparipennata"},{"id":"71_species_fraxinus_ornus","nomeSci":"Fraxinus ornus","famiglia":"Oleaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":71,"note":"Diverso dal maggiore per corteccia liscia. GEMMA CHE SOMIGLIA A \"PIEDINO DI PORCO, CON UNGHIA GRIGIA\". Fioritura ornamentale che avviene prima delle foglie, bel fiore al profumo di miele. Foglia composta imparipennata, con foglioline ovali e leggermente peduncolate e meno lunghe ( da 3 a 5 contro le 7 dell'excelsior)","fogliaTipo":"composta","fogliaComposta":"imparipennata"},{"id":"72_species_fraxinus_angustifolia","nomeSci":"Fraxinus angustifolia","famiglia":"Oleaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":72,"note":"Foglie più sottili e maggiore leggerezza GEMMA A ZOCCOLO MA DI COLORE MARRONE. Foglia composta imparipennata ma più stretta e dentata Fioritura verde coperte dalle foglie, poco significativa","fogliaTipo":"composta","fogliaComposta":"imparipennata"},{"id":"73_species_juglans_regia","nomeSci":"Juglans regia","famiglia":"Junglandaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":73,"note":"NOCE EUROPEO. PIANTA POSSENTE, APPARTO RADICALE, ROVESCIA CORDOLI E MURI. Albero da frutto. Legno di eccezionale qualità poiché a crescita lenta. Fusto fortemente solcato, quando invecchia ha striature argentate, liscia da giovane. Foglia composta, imparipennata, foglia centrale più grande delle altre, foglie alterne; se stropicciate si avverte l'aroma del noce. PIANTA MONOICA FRUTTO DRUPA LA CUI PARTE CARNOSA (MALLO) SI DECOMPONE LIBERANDO IL NOCCIOLO ( NOCE) CHE CONTIENE UN SEME (GHERIGLIO) Fioritura tra aprile e maggio","fogliaTipo":"composta","fogliaComposta":"imparipennata"},{"id":"74_species_juglans_nigra","nomeSci":"Juglans nigra","famiglia":"Junglandaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"america del nord","varieta":null,"isVarieta":false,"pagina":74,"note":"Corteccia scurissima a rombi molto grandi ( più grandi di acero platanoide e frassino) Meno regale del nostro nocciolo; Ottima per filari. Produce noci enormi .Caratteristica con vegetazione a raggera, prevalentemente apicale. Foglia composta sia polipennata che imparipennata (confondibile con frassino). Foglie lunghe con prima coppia di FOGLIOLINE GIRATE AL CONTRARIO E NON VERSO LA PUNTA . NOCI NON COMMESTIBILI FOGLIE FORTEMENTE AROMATICHE MA VERSO L'AGRUME; TOLTO IL MALLO troviamo una noce molto più piccola della nostra non apribile se non con il martello","gemmePosizione":"apicale","fogliaTipo":"composta","fogliaComposta":"imparipennata"},{"id":"75_variety_ailanthus_altissima","nomeSci":"Ailanthus altissima","famiglia":"Simaroubaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"cina","varieta":null,"isVarieta":true,"pagina":75,"note":"Completamente pieno semi IMPOSSIBILE DA ABBATTERE ; va capitozzata fino alla Morte, poiché da ogni radice spunta una pianta. INFESTANTE PIU' DELLA ROBINIA NON UTILIZZARE COME ALBERO ORNAMENTALE. Pianta dioica ; Frutto Samara D'inverno facile da riconoscere perché ha i rami verticillati Cresce velocissimo, flessibilissimo, qualità pessima ma impossibile da spezzare Foglia grandissima fino a mezzo metro, paripennata ,nella maggior parte dei casi. Foglioline con margine liscio con dentatura poco evidente, se stropicciata odora di popcorn In primavera si vede vegetazione arancione apicale Samare arricciate ad elica","ramiInserzione":"verticillati","gemmePosizione":"apicale","fogliaComposta":"paripennata"},{"id":"76_species_koelreuteria_paniculata","nomeSci":"Koelreuteria paniculata","famiglia":"Sapindaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"cina, corea","varieta":null,"isVarieta":false,"pagina":76,"note":"Corteccia marrone con fessure profonde. Frutti a capsula a forma di cuore con tre lati, verdi d'estate, a lungo persistenti e di colore marrone in inverno. Foglia composta imparipennata, lunga fino a 40 cm, con 7 - 17 foglioline pelose, verde scuro sulla pagina superiore. Fiori piccoli, gialli, in pannocchie, sulla sommità dei rami in estate","fogliaTipo":"composta","fogliaComposta":"imparipennata"},{"id":"77_species_robinia_pseudoacacia","nomeSci":"Robinia pseudoacacia","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"stati uniti sud orientali","varieta":null,"isVarieta":false,"pagina":77,"note":"Utilizzata come pianta pioniera per fertilizzare terreni incolti; Vive anche in terreni poveri e con la sua caduta delle foglie arricchisce il terreno di S.O. ASSOLUTAMENTE NON POTARE (INFESTANTE) Ottimo combustibile nonostante legno giovane, brucia lentamente. Nella fioritura esteticamente gradevole attira moltissime api (MIELE DI ACACIA). Tronco liscio da giovane e molto rugoso quando invecchia. Foglie alterne imparipennate composte da 11-17 foglioline ovali con punte arrotondate.. ALLA BASE PRESENTA SPINE . Fiore bianco, FRUTTO LEGUMINOSO, grande con semi all'interno"},{"id":"78_variety_robinia_pseudoacacia","nomeSci":"Robinia pseudoacacia","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"stati uniti sud orientali","varieta":"Umbraculifera","isVarieta":true,"pagina":78,"note":"VARIETA' CON CHIOMA DI FORMA SFERICA"},{"id":"79_variety_robinia_pseudoacacia","nomeSci":"Robinia pseudoacacia","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"stati uniti sud orientali","varieta":"Casque Rouge","isVarieta":true,"pagina":79,"note":"VARIETA' A FIORITURA ROSA"},{"id":"80_variety_robinia_pseudoacacia","nomeSci":"Robinia pseudoacacia","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"stati uniti sud orientali","varieta":"Piramidalis","isVarieta":true,"pagina":80,"note":"VARIETA' A CHIOMA FASTIGIATA","chiomaForma":"fastigiata"},{"id":"81_variety_robinia_pseudoacacia","nomeSci":"Robinia pseudoacacia","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"stati uniti sud orientali","varieta":"Frisia","isVarieta":true,"pagina":81,"note":"VARIETA' CON FOGLIE DI COLORE FORTEMENTE GIALLASTRO IN PRIMAVERA DI COLORE VERDE MELA IN ESTATE"},{"id":"82_species_albizia_julibrissin","nomeSci":"Albizia julibrissin","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"asia sud occidentale","varieta":null,"isVarieta":false,"pagina":82,"note":"Chiamata Acacia di Costantinopoli Rami giovani molto lunghi. Chioma fortemente ad ombrello che si allarga molto, interessante come pianta da parcheggio Quando fiorisce emette un piumino appiccicoso. Foglia composta bipennata, lunga fino a 20 cm, fiorisce a maggio/giugno Frutto (legume) a forma di fagiolini che rimangono sulla pianta anche in inverno","chiomaForma":"ad ombrello","fogliaTipo":"composta","fogliaComposta":"bipennata"},{"id":"83_species_sophora_japonica","nomeSci":"Sophora japonica","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"giappone e cina","varieta":null,"isVarieta":false,"pagina":83,"note":"Maestosa, bellissima, fiorisce su tutte le punte dei rami. Foglia simile alla robinia, imparipennata ma con FOGLIOLINE APPUNTITE. Produce un legume, strani frutti attaccati alla pianta, A forma di palline in fila indiana, che perdurano tutto l'inverno con baccello acquoso. Fioritura tra maggio e giugno","fogliaComposta":"imparipennata"},{"id":"84_variety_sophora_japonica","nomeSci":"Sophora japonica","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone e cina","varieta":"Pendula","isVarieta":true,"pagina":84,"note":"VARIETA' CON CARATTERISTICI RAMI ARCUATI QUANDO SPOGLI A DI NOTEVOLE EFFETTO. POCO APPARISCENTE QUANDO COPERTA CRESCITA MOLTO LENTA"},{"id":"85_species_gleditsia_tricanthos","nomeSci":"Gleditsia tricanthos","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"america del nord","varieta":null,"isVarieta":false,"pagina":85,"note":"CHIAMATA SPINA DI GIUDA Albero anonimo, poco caratteristico. In inverno fagioli lunghissimi, persistenti, antiestetici, confusi con Carrubo. Spine molto lunghe ed acuminate ( sono in realtà gemme, in primavera scompaiono) Foglia a volte imparipennata ed a volte bipennata, con foglioline piccole ed ovali. Fioritura estiva colore bianco-crema","fogliaComposta":"imparipennata; bipennata"},{"id":"86_variety_gleditsia_tricanthos","nomeSci":"Gleditsia tricanthos","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"america del nord","varieta":"Sunburst","isVarieta":true,"pagina":86,"note":"NON FIORISCE E NON PRODUCE FRUTTI, FOGLIE DI COLORE GIALLO IN PRIMAVERA E POI VERDE MELA"},{"id":"87_variety_gleditsia_tricanthos","nomeSci":"Gleditsia tricanthos","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"america del nord","varieta":"Inermis","isVarieta":true,"pagina":87,"note":"VARIETA' PRIVA DI SPINE TRATTANDOSI DI FOGLIOLINE MODIFICATE, E' RICONOSCIBILE IN INVERNO"},{"id":"88_species_cercis_siliquastrum","nomeSci":"Cercis siliquastrum","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa s.o. - asia occid.","varieta":null,"isVarieta":false,"pagina":88,"note":"Prettamente mediterranea ma si adatta benissimo. Chiamato impropriamente Albero di Giuda, in realtà il nome corretto e' \"Albero della Giudea\". Corteccia molto rugosa da anziano. Fioritura rosa, precoce a marzo, a grappolo, precede la foliazione. Fiori ovunque, anche su fusto e rami già grossi. Foglia facilissima da riconoscere di forma rotonda, a base cordata, semplice, non composta. Frutto legume , con presenza di legumi","fogliaTipo":"semplice","fogliaLamina":"rotonda","fogliaBase":"cordata"},{"id":"89_variety_cercis_siliquastrum","nomeSci":"Cercis siliquastrum","famiglia":"Fabaceae - Ex Leguminose","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa s.o. - asia occid.","varieta":"Alba","isVarieta":true,"pagina":89,"note":"VARIETA' CON FIORE BIANCO"},{"id":"90_species_catalpa_bignonioides","nomeSci":"Catalpa bignonioides","famiglia":"Bignoniaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"stati uniti del sud","varieta":null,"isVarieta":false,"pagina":90,"note":"Chiamato l'albero dei sigari, per presenza insistente dei frutti sugli alberi. Chioma a branche spesso ricurve. Corteccia caratteristica con macchie scure ed arancioni. Foglia molto grande, ovale e cuoriforme a base cordata, fiorisce a maggio/giugno, Foglie pelose, senza lobi, con margine seghettato. Fiore bianco estivo, a trombetta. FRUTTO bacello cilindrico (capsula) fino a 20/40 cm","fogliaLamina":"cordata","fogliaMargine":"seghettato","fogliaBase":"cordata"},{"id":"91_variety_catalpa_bignonioides","nomeSci":"Catalpa bignonioides","famiglia":"Bignoniaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"stati uniti del sud","varieta":"Aurea","isVarieta":true,"pagina":91,"note":"VARIETA' CON FOGLIE GIALLO-VERDI IN ESTATE"},{"id":"92_species_paulownia_tomentosa","nomeSci":"Paulownia tomentosa","famiglia":"Scrofuliaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"cina","varieta":null,"isVarieta":false,"pagina":92,"note":"PIANTA INFESTANTE Foglie enormi !!! FIORITURA DI COLORE VIOLA ( amata come bonsai) In inverno sui rami si trovano contemporaneamente Grappoli, gemme fiorali e quelli dei frutti formati nell'estate precedente. Frutto, capsula, tipo piccola noce ( molti ed infestanti) Foglia molto grande, pelosa, si confonde con quella della catalpa ma alla base c'è un accenno di lobi"},{"id":"93_species_liquidambar_styraciflua","nomeSci":"Liquidambar styraciflua","famiglia":"Altingiageae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"america n. e messico","varieta":null,"isVarieta":false,"pagina":93,"note":"RAMI RICOPERTI DA CRESTE. Foglia palmata, con lobi, picciolo lungo e foglia finemente dentata. LOBI A MARGINE ARROTONDATO CON PICCIOLO INSERITO SOTTO LA NERVATURA CENTRALE FORMANDO UN ANGOLO DI 90°. In autunno prende il colore rossiccio. Frutto molto grosso ( non disamara) pallina molto dura, da non confondersi con quella del platano","fogliaLamina":"palmata","fogliaApice":"arrotondato"},{"id":"94_variety_liquidambar_styraciflua","nomeSci":"Liquidambar styraciflua","famiglia":"Altingiageae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"america del n. e messico","varieta":"Red Star","isVarieta":true,"pagina":94,"note":"VARIETA' CON FOGLIE MOLTO SCURE IN AUTUNNO"},{"id":"95_species_populus_nigra","nomeSci":"Populus nigra","famiglia":"Salicaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa e asia occid.","varieta":null,"isVarieta":false,"pagina":95,"note":"PIANTA DIOICA Corteccia scura con fessurazioni longitudinali, spesso con grosse protuberanze. Gemme allungate con apici ricurvi, vischiose, resinose. Foglia romboidale con margine seghettato. Picciolo della foglia a sezione rotonda. La femmina produce frutti che quando aperti sono lanuginosi Il frutto è una capsula, con semi avvolti da piumino bianco (pappo)","fogliaLamina":"romboidale","fogliaMargine":"seghettato"},{"id":"96_variety_populus_nigra","nomeSci":"Populus nigra","famiglia":"Salicaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa e asia occid.","varieta":"Italica","isVarieta":true,"pagina":96,"note":"VARIETA' OTTENUTA DA CLONAZIONE DI UNA PIANTA MASCHIO SI RIPRODUCE SOLO PER TALEA DETTO ANCHE PIOPPO CIPRESSINO PORTAMENTO COLONNARE, FOGLIA PIU' PICCOLA CON BASE ALLARGATA"},{"id":"97_species_populus_alba","nomeSci":"Populus alba","famiglia":"Salicaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa e asia occid.","varieta":null,"isVarieta":false,"pagina":97,"note":"Corteccia bianchissima da giovane, scura invecchiando. Foglia lobata, 3/5 lobi, non a triangolo, PAGINA INFERIORE BIANCA !!! Il frutto è una capsula, con semi avvolti da piumino Bianco (pappo). DETTO ANCHE PIOPPO BIANCO","fogliaLamina":"lobata"},{"id":"98_species_populus_tremula","nomeSci":"Populus tremula","famiglia":"Salicaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa e asia occid.","varieta":null,"isVarieta":false,"pagina":98,"note":"Corteccia bianca CARATTERISTICA FOGLIA ARROTONDATA CON DENTATURA ARROTONDATA"},{"id":"99_species_salix_x","nomeSci":"Salix x","famiglia":"Salicaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"cina","varieta":null,"isVarieta":false,"pagina":99,"note":"IBRIDO PIANTA DIOICA SALICE PENDULO Lunghi rami penduli e di colore giallo nelle parti più giovani.; la sua presenza è legata ai corsi d'acqua, a terreni fertili soggetti a sommersione. Foglia lanceolata con leggera peluria argentea , su entrambe le pagine","fogliaLamina":"lanceolata"},{"id":"100_species_salix_babylonica","nomeSci":"Salix babylonica","famiglia":"Salicaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"cina","varieta":null,"isVarieta":false,"pagina":100,"note":"PIANTA DIOICA SALICE PIANGENTE Lunghi rami penduli e di colore bruno-rossastro nelle parti più giovani; la sua presenza è legata ai corsi d'acqua, a terreni fertili soggetti a sommersione. Foglia lanceolata con leggera peluria argentea , Sulla pagina inferiore","chiomaForma":"piangente","fogliaLamina":"lanceolata"},{"id":"101_variety_salix_matsudana","nomeSci":"Salix matsudana","famiglia":"Salicaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"cina","varieta":"Tortuosa","isVarieta":true,"pagina":101,"note":"PIANTA DIOICA SALICE CONTORTO Ramificazione leggera sinuosa e contorta. Utilizzato spesso a Natale per le decorazioni Foglia lanceolata arricciata e contorta","fogliaLamina":"lanceolata"},{"id":"102_species_celtis_australis","nomeSci":"Celtis australis","famiglia":"Ulmaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa m. - asia sud occ.","varieta":null,"isVarieta":false,"pagina":102,"note":"NOME VOLGARE - BAGOLARO Pianta autoctona Radici possenti, solleva i marciapiedi ed i muri di casa Corteccia liscia come quella dei faggi ma molto più opaca. Gemme appressate, attaccate al ramo, (quelle del Fagus lunghe appuntite e divergenti) Foglia ovale dentata, e punta arricciolata Frutto \"bagola\"","gemmeOrientamento":"appressate; divergenti"},{"id":"103_species_carpinus_betulus","nomeSci":"Carpinus betulus","famiglia":"Corylaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa - asia sud occ.","varieta":null,"isVarieta":false,"pagina":103,"note":"Caratteristica tronco con costole muscolose . Foglia semplice ovale, con margine DOPPIAENTE SEGHETTATO e con costolature evidenti tra le nervature. Foglie persistenti in inverno non si distaccano fino al rilascio della abscissina, che avviene solo all'apertura delle nuove gemme. Frutto a grappolo, formato da piccole noci protette da una bratta, (fogliolina modificata), trilobata con lobo centrale più lungo","fogliaTipo":"semplice","fogliaMargine":"seghettato"},{"id":"104_variety_carpinus_betulus","nomeSci":"Carpinus betulus","famiglia":"Corylaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"2","provenienza":"europa - asia sud occ.","varieta":"Fastigiata","isVarieta":true,"pagina":104,"note":"VARIETA' FASTIGIATA O PYRAIDALIS CON PORTAMENTO PRIAMIDALE","chiomaForma":"fastigiata"},{"id":"105_variety_prunus_cerasifera","nomeSci":"Prunus cerasifera","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"autoctono","varieta":"Pissardii","isVarieta":true,"pagina":105,"note":"SUSINO SELVATICO Corteccia scura, quasi nera. Foglia ovata con margine seghettato di colore rosso Porpora. Fioritura bianca ancora prima della foliazione. Frutto carnoso (drupa), simile ad una prugna","fogliaLamina":"ovata","fogliaMargine":"seghettato"},{"id":"106_variety_prunus_serrulata","nomeSci":"Prunus serrulata","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Kanzan","isVarieta":true,"pagina":106,"note":"CILIEGIO GIAPPONESE Corteccia ad anelli tipica dei ciliegi selvatici, innestato a Corona sui selvatici. Fusto classico dei ciliegi, anellato, innestato a corona sul ciliegio. PORTAMENTO A SCOPA ROVESCIATA. Foglie ampie, acute ed acuminate, di colore verde scuro, con margine seghettato. Fioritura immensa, con fiori doppi fino a 4 cm, a grappoli di 3-5 elementi, sorretti da un peduncolo con brattee; fioritura a volte precoce","fogliaMargine":"seghettato"},{"id":"107_variety_prunus_serrulata","nomeSci":"Prunus serrulata","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Amanogawa","isVarieta":true,"pagina":107,"note":"CILIEGIO GIAPPONESE VARIETA' CON PORTAMENTO MOLTO STRETTO A COLONNA Foglie lunghe e strette, finemente dentate"},{"id":"108_species_prunus_sargentii","nomeSci":"Prunus sargentii","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":null,"isVarieta":false,"pagina":108,"note":"CILIEGIO GIAPPONESE Corteccia rosso-marrone, lucida con lenticelle. Rami giovani di colore rossastrbronzo. Foglie obovate, alterne, con margine seghettato , che terminano con una lunga punta. Fiori singoli, rosa pallido","fogliaMargine":"seghettato"},{"id":"109_variety_prunus_serrulata","nomeSci":"Prunus serrulata","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Accolade","isVarieta":true,"pagina":109,"note":"NATO DA INCROCIO DI PRUNUS SARGENTII X PRUNUS X SUBHIRTELLA Foglie ovali dentate con punta molto lunga e ghiandole alla base della foglie. Fiori semidoppi bianco-rosati prima delle foglie"},{"id":"110_species_prunus_x","nomeSci":"Prunus x","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":null,"isVarieta":false,"pagina":110,"note":"IBRIDO INCROCIO NATURALE DI PRUNUS INCISA E PRUNUS PENDULA Corteccia grigio-marrone, liscia e striata con lenticelle. Foglie ovali dentate con punta molto lunga e ghiandole alla base della foglie. Fiori semidoppi bianco-rosati prima delle foglie. FRUTTO PICCOLO, NERO, di 1 cm"},{"id":"111_variety_prunus_x","nomeSci":"Prunus x","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Autumnalis","isVarieta":true,"pagina":111,"note":"VARIETA' CON FIORITURA TARDO AUTUNNO-INVERNO CON PICCOLI FIORI DOPPI"},{"id":"112_variety_prunus_x","nomeSci":"Prunus x","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Pendula","isVarieta":true,"pagina":112,"note":"VARIETA' CON RAMI PENDULI E FIORI SINGOLI PORTATI IN FITTI GRAPPOLI"},{"id":"113_species_malus_floribunda","nomeSci":"Malus floribunda","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":null,"isVarieta":false,"pagina":113,"note":"CARATTERISTICA FOGLIA OPACA CON ANTERE DI COLORE GIALLO (NEL PYRUS SONO ROSSE) Corteccia porpora-marrone Chioma espansa. Foglia ellittica, lunga con punta affusolata e denti acuti, verde scuro. Fiori bianchi a metà primavera, con antere di color giallo. Frutto piccola mela","chiomaForma":"espansa","fogliaLamina":"ellittica"},{"id":"114_variety_malus_floribunda","nomeSci":"Malus floribunda","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Evereste","isVarieta":true,"pagina":114,"note":"VARIETA' CON FIORI BIANCHI E FRUTTO ARANCIO"},{"id":"115_variety_malus_floribunda","nomeSci":"Malus floribunda","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Golden Hornel","isVarieta":true,"pagina":115,"note":"VARIETA' CON FIORI BIANCHI E FRUTTO GIALLO"},{"id":"116_variety_malus_floribunda","nomeSci":"Malus floribunda","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Profusion","isVarieta":true,"pagina":116,"note":"VARIETA' CON FIORE PORPORA E FRUTTO ROSSO"},{"id":"117_variety_malus_floribunda","nomeSci":"Malus floribunda","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"giappone","varieta":"Red Sentinel","isVarieta":true,"pagina":117,"note":"VARIETA' CON FIORE BIANCO E FRUTTTO ROSSO-GIALLO"},{"id":"118_variety_pyrus_calleryana","nomeSci":"Pyrus calleryana","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"cina, vietnam","varieta":null,"isVarieta":true,"pagina":118,"note":"CARATTERISTICA FOGLIA LUCIDA, PIEGATA A META' LUNGO LA NERVATURA CENTRALE ANTERE DI COLOR ROSSO. Corteccia grigia scura. Chioma piramidale che si allarga molto alla base. Foglia semplice, ovale, verde scuro e lucida sopra, più chiara sotto. Fiori bianchi a cinque petali a primavera all'inizio della foliazione. Frutti a forma di piccola pera color ruggine","chiomaForma":"piramidale","fogliaTipo":"semplice"},{"id":"119_variety_pyrus_calleryana","nomeSci":"Pyrus calleryana","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"cina, vietnam","varieta":"Chanticleer","isVarieta":true,"pagina":119,"note":"VARIETA' CON CHIOMA AFFUSOLATA PIU' STRETTA DELLA SPECIE FIORE SEMPRE DI COLOR BIANCO"},{"id":"120_species_crataegus_monogyna","nomeSci":"Crataegus monogyna","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":120,"note":"BIANCOSPINO Corteccia che si squama Rami giovani bruno-rossicci con SPINE Foglie molto variabili, con 3-7 lobi a volte accennate ed a volte molto profondi, a margine intero o con pochi denti verso l'apice. Fioritura bianca da inizio estate Frutto rosso con un solo seme all'interno","fogliaMargine":"intero"},{"id":"121_variety_crataegus_laevigata","nomeSci":"Crataegus laevigata","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"europa","varieta":null,"isVarieta":true,"pagina":121,"note":"CORTECCIA GRIGIA E LISCIA , FESSURATA IN ETA' AVANZATA. Rami giovani bruno-rossicci con SPINE Foglie con 2-3 lobi poco profondi, con punte rivolte verso la punta della foglia. Fioritura bianca o rosa pallido ad inizio estate Frutto GROSSO 1 cm, con duo o tre semi all'interno"},{"id":"122_variety_crataegus_laevigata","nomeSci":"Crataegus laevigata","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"europa","varieta":"Paul Scarlet","isVarieta":true,"pagina":122,"note":"VARIETA' CON FIORI DOPPI DI COLORE ROSSO CHIARO"},{"id":"123_species_eriobotrya_japonica","nomeSci":"Eriobotrya japonica","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"sempreverde","grandezza":"3","provenienza":"giappone","varieta":null,"isVarieta":false,"pagina":123,"note":"NESPOLO DEL GIAPPONE Tutte le parti giovani sono pelose Foglie MOLTO GRANDI, fino a 25 cm, di consistenza coriacea, molto scure e PIEGHETTATE sulla pagina superiore, più chiare sotto e pelose. Fiori bianci con infloriescenze a grappolo PROFUMATE all'inizio dell'estate. Frutto giallo-arancio con due grossi semi all'interno, in autunno"},{"id":"124_species_sorbus_aucuparia","nomeSci":"Sorbus aucuparia","famiglia":"Rosaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"europa centrale e settentr.","varieta":null,"isVarieta":false,"pagina":124,"note":"SORBO DEGLI UCCELLATORI Corteccia grigia e liscia. Gemme non appiccicose con peli grigi. Foglia composta imparipennata con 11-15 foglioline a margine dentato. Fiori bianchi primaverili in inflorescenze a cupola, fortemente profumati Frutti piccoli e tondi, dapprima giallo aranciati, poi in maturità","fogliaTipo":"composta","fogliaComposta":"imparipennata","fogliaMargine":"dentato"},{"id":"125_species_morus_nigra","nomeSci":"Morus nigra","famiglia":"Moraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"cina e giappone","varieta":null,"isVarieta":false,"pagina":125,"note":"GELSO DELLA CINA, ERRONEAMENTE CONSIDERATO AUTOCTONO. Chioma larga. Foglie alterne, semplicI, ovali con margine dentato, a base cordata, verde scuro e RUVIDE SOPRA pelose sotto. Frutto, composto da piccole drupe carnose rosso-violacee, commestibili. Note: Forma di allevamento a testa di salice; legno debole che scoscia; Sopporta tutti i tipi di potature. Albero della tradizione lombarda ripreso come pianta ornamentale nell'arredamento urbano Potature portano via rami su cui fiorisce. Fiorisce abbondantemente sui rami dell'anno","fogliaLamina":"cordata","fogliaMargine":"dentato","fogliaBase":"cordata"},{"id":"126_species_morus_alba","nomeSci":"Morus alba","famiglia":"Moraceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"caducifoglia","grandezza":"3","provenienza":"cina e giappone","varieta":null,"isVarieta":false,"pagina":126,"note":"GELSO BIANCO. Chioma larga. Foglie alterne, semplici, ovali con margine dentato, a base cordata, verde scuro, LUCIDE E LISCE SOPRA TALVOLTA CON TRE LOBI. Frutto, composto da piccole drupe carnose bianco-rosate, Commestibili ma meno saporite del morus nigra. Note: Forma di allevamento a testa di salice; legno debole che scoscia; Sopporta tutti i tipi di potature. Albero della tradizione lombarda ripreso come pianta ornamentale nell'arredamento urbano Potature portano via rami su cui fiorisce. Fiorisce abbondantemente sui rami dell'anno","fogliaLamina":"cordata","fogliaMargine":"dentato","fogliaBase":"cordata"},{"id":"128_species_chamaerops_humilis","nomeSci":"Chamaerops humilis","famiglia":"Arecaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"ex palme","grandezza":"3","provenienza":"hymalaia, cina del nord","varieta":null,"isVarieta":false,"pagina":128,"note":"PALMA NANA Pianta mediterranea che si adatta fino a temperature di 5 gradi sotto zero. Foglie coriacee non degradabili, occorre utilizzo del cippatore Spinosa"},{"id":"129_variety_chamaerops_humilis","nomeSci":"Chamaerops humilis","famiglia":"Arecaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"ex palme","grandezza":"3","provenienza":"hymalaia, cina del nord","varieta":"Elegans","isVarieta":true,"pagina":129,"note":"VARIETA' CON FOGLIE GRIGIO-VERDI SULLA PAGINA INFERIORE"},{"id":"130_variety_chamaerops_humilis","nomeSci":"Chamaerops humilis","famiglia":"Arecaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"ex palme","grandezza":"3","provenienza":"hymalaia, cina del nord","varieta":"Tomentosa","isVarieta":true,"pagina":130,"note":"VARIETA' CON FOGLIE BIANCO-LANOSE SULLA PAGINA INFERIORE"},{"id":"131_species_trachycarpus_fortunei","nomeSci":"Trachycarpus fortunei","famiglia":"Arecaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"ex palme","grandezza":"3","provenienza":"hymalaia, cina n, india n.","varieta":null,"isVarieta":false,"pagina":131,"note":"PIANTA INFESTANTE PER IL GUSTO DEI FRUTTICINI, APPETIBILI DAGLI UCCELLI. TOLLERA TEMPERATURE ANCHE DI -7°. Fusto unico non cespuglioso, ricoperto da fibre brune persistenti e da piccioli delle foglie morte. Foglie a ventaglio di colore verde scuro, con incisioni fino a metà del diametro, flesse alla sommità. Picciolo lungo leggermente denticolato privo di uncini. Frutti, datterini, persistenti di colore violaceo"},{"id":"132_variety_phoenix_canariensis","nomeSci":"Phoenix canariensis","famiglia":"Arecaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"ex palme","grandezza":"2","provenienza":"canarie","varieta":null,"isVarieta":true,"pagina":132,"note":"PALMA DELLE CANARIE DIFFUSISSIMA IN LIGURIA. TEME PERO' IL GELO DI CRESCITA VELOCE CON FOGLIA PENNATA"},{"id":"133_species_washingtonia_robusta","nomeSci":"Washingtonia robusta","famiglia":"Arecaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"sempreverde","grandezza":"1","provenienza":"messico","varieta":null,"isVarieta":false,"pagina":133,"note":"PALMA DEL MESSICO FUSTO QUASI LISCIO, SOTTILE, stride con il nome. Foglie grandi, palmate, erette, rade e meno incise della W.filifera. Margini terminano con filamenti bianche ma meno evidenti; foglie rimangono attaccate al tronco. Picciolo con forti spine brune ad uncino. Frutti drupacei abbondanti piccoli e neri"},{"id":"134_variety_washingtonia_filifera","nomeSci":"Washingtonia filifera","famiglia":"Arecaceae","divisione":"ANGIOSPERME-MAGNOLIOPHYTA","tipologia":"sempreverde","grandezza":"1","provenienza":"messico","varieta":null,"isVarieta":true,"pagina":134,"note":"PALMA DEL MESSICO FUSTO MOLTO FORTE E GROSSO IL NOME STRIDE CON VARIETA' 'ROBUSTA' CHE RIMANE MOLTO SOTTILE ,SALENDO PER TANTISSIMI METRI. L'ORIGINE DEL NOME DERIVA DALLE FOGLIE PENZOLANTI, QUANDO IN DECOMPOSIZIONE FORMANO UNA LUNGA BARBA SOTTO LA CHIOMA VERDE PICCIOLO CON PICCOLE SPINE GIALLE UNCINATE"},{"id":"137_species_ginkgo_biloba","nomeSci":"Ginkgo biloba","famiglia":"Ginkoaceae","divisione":"GIMNOSPERME-PINOPHYTA","tipologia":"caducifoglia","grandezza":"1","provenienza":"cina","varieta":null,"isVarieta":false,"pagina":137,"note":"PIANTA DIOICA. Pianta da grande parco con crescita monopodiale, dove i rami laterali non riescono a recuperare l'altezza della cima ( al contrario della simpodiale). Crescita a palchi inseriti a raggiera nel fusto. Esile e poco ramificata da giovane, invecchiando può arrivare a 30 - 40 metri e diametro di chioma 20 metri Foglia a ventaglio, flabello, unica nel suo genere. D'inverno rametti secondari con presenza di BRACHIBLASTI con gemma, tipico delle GIMNOSPERME ( larix decidua simile ma è pianta di alta montagna e produce pigne). Frutto, piccola prugna dall'odore sgradevole","fogliaLamina":"flabello"},{"id":"140_variety_araucaria_araucana","nomeSci":"Araucaria araucana","famiglia":"Araucariaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"araucaria, cile","varieta":null,"isVarieta":true,"pagina":140,"note":"PIANTA DIOICA. TUTTI I RAMI VOLGONO VERSO L'ALTO FUSTO PULITO. Rami giovani coperti dalle foglie. Rami in palchi orizzontali verticillati e decidui dopo diversi anni. Foglie a forma di squama triangolare di colore verde intenso, sovrapposte in modo serrato e spiralato, con apice acuto e spina. Strobilo grosso ovale e bruno che cade in pezzi in età matura","ramiInserzione":"verticillati"},{"id":"141_species_taxus_baccata","nomeSci":"Taxus baccata","famiglia":"Taxaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"europa, asia","varieta":null,"isVarieta":false,"pagina":141,"note":"PIANTA DIOICA. Diffusissimo in passato; pianta completamente velenosa. In Inghilterra usato in ars-topiaria. Di crescita lenta Foglia ad ago ma molto morbido, a sezione appiattita e disposti a pettine, di colore verde scuro sulla pagina superiore, più pallido il colore su quella inferiore. Frutto di nome ARILLO CARNOSO di colore rosso, a campana, aperto verso il basso, che lascia intravedere un seme di colore bluastro"},{"id":"142_variety_taxus_baccata","nomeSci":"Taxus baccata","famiglia":"Taxaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"europa, asia","varieta":"Fastigiata","isVarieta":true,"pagina":142,"note":"VARIETA' A CHIOMA FASTIGIATA E' PRESENTE ANCHE UNA VARIETA' FASTIGIATA AUREA","chiomaForma":"fastigiata"},{"id":"143_species_taxodium_disticum","nomeSci":"Taxodium disticum","famiglia":"Taxodiaceae","divisione":"CONIFERE","tipologia":"caducifoglia","grandezza":"1","provenienza":"stati uniti sud orientali","varieta":null,"isVarieta":false,"pagina":143,"note":"Corteccia spessa e fibrosa bruno-rossiccia, con lunghe screpolature longitudinali FORMAZIONE DI RADICI EMERGENTI DAL TERRENO, cilindriche, dette PNEUMATOFORI. Foglie ad ago appiattito, di colore verde brillante, inserite a pettine su rametti, alternati sul ramo principale. Strobili globosi, glabri, costituiti da squame a forma di chiodo, che si disfano alla maturità raggiunta"},{"id":"144_species_cryptomeria_japonica","nomeSci":"Cryptomeria japonica","famiglia":"Taxodiaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"asia","varieta":null,"isVarieta":false,"pagina":144,"note":"Corteccia sottile rosso-bruno, fibrosa, che si fessura e stacca in lunghe strisce longitudinali. Aghi a sezione QUADRANGOLARE, con APICE INCURVATO verso il rametto, disposti a spirale. Stobili bruni, globosi, solitari, con 20-40 squame, ciascuna con 4/6 punte spinescienti"},{"id":"145_variety_metasequoia_glyptostroboides","nomeSci":"Metasequoia glyptostroboides","famiglia":"Taxodiaceae","divisione":"CONIFERE","tipologia":"caducifoglia","grandezza":"1","provenienza":"cina","varieta":null,"isVarieta":true,"pagina":145,"note":"ABETE D'ACQUA - ATTENZIONE CADUCIFOGLIA Generalmente, nelle classificazioni tradizionali che questi generi vengono inclusi nella famiglia delle Cupressacee, ma alcuni autori li uniscono al genere Taxodium e pochi altri generi nella famiglia delle Taxodiacee. Il portamento è piramidale e l'altezza può raggiungere i 40 metri. La scorza è bruno-rossastra. Le foglie sono piatte e lunghe 2-3 centimetri. È una delle poche conifere che in autunno perde le foglie","chiomaForma":"piramidale"},{"id":"147_species_cupressus_sempervirens","nomeSci":"Cupressus sempervirens","famiglia":"Cupressaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"mediterraneo orientale","varieta":null,"isVarieta":false,"pagina":147,"note":"Corteccia grigio-bruna sottile, fibrosa, finemente fessurata longitudinalmente. Rametti apicali a sezione QUADRANGOLARE. Squame di colore verde cupo, ad apice arrotondato. Strobili solitari o a gruppi, ovali o globosi, VERDI E POI MARRONI, con SQUAME PENTAGOLALI PIATTE","fogliaApice":"arrotondato"},{"id":"148_variety_cupressus_sempervirens","nomeSci":"Cupressus sempervirens","famiglia":"Cupressaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"mediterraneo orientale","varieta":"Stricta","isVarieta":true,"pagina":148,"note":"VARIETA' A FORMA COLONNARE MOLTO STRETTA"},{"id":"149_variety_cupressus_arizonica","nomeSci":"Cupressus arizonica","famiglia":"Cupressaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"arizona","varieta":null,"isVarieta":true,"pagina":149,"note":"CIPRESSO DELL' ARIZONA. Corteccia dapprima rosso-bruna, nei soggetti maturi grigiastra, che si fessura in lunghe strisce longitudinali persistenti. Rami giovani a SEZIONE QUADRANGOLARE. Squame con essudazione di resina bianca, di colore grigio-verde o glauche, di odore sgradevole se stropicciate. Stroboli con squame provviste di \"processo spinoso\" o punta","fogliaMargine":"spinoso"},{"id":"150_species_juniperus_communis","nomeSci":"Juniperus communis","famiglia":"Cupressaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"2","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":150,"note":"GINEPRO. PORTAMENTO SOLITAMENTE CESPUGLIOSO. Corteccia grigio-bruna che si sfalda in lunghe strisce cartacee. Rametti a SEZIONE TRIANGOLARE Foglie aghiformi rigide e pungenti in verticilli di 3, di colore verde glauco sulla pagina superiore, dove presentano una scanalatura con linea bianca; pagina inferiore verde. Stroboli pseudobacche dette \"galbuli\" nere o nerazzurate, coperte da pruina cerosa una volta maturate"},{"id":"151_species_calocedrus_decurrens","nomeSci":"Calocedrus decurrens","famiglia":"Cupressaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"america settentrionale","varieta":null,"isVarieta":false,"pagina":151,"note":"PIANTA DIOICA. CHIAMATO ANCHE LIBOCEDRUS. Corteccia liscia da giovane, a maturità diventa bruno- rossastra, lucida liscia e molto scanalata. Foglie a squame. SQUAMA FACCIALE ALLA STESSA ALTEZZA DELLE LATERALI. Rami giovani a sezione piatta. Frutto formato da DUE ALI che si aprono ed al loro interno sono presenti due semi","fogliaTipo":"a squame"},{"id":"152_species_chamaecyparis_lawsoniana","nomeSci":"Chamaecyparis lawsoniana","famiglia":"Cupressaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"2","provenienza":"stati uniti occidentali","varieta":null,"isVarieta":false,"pagina":152,"note":"FALSO CIPRESSO Corteccia fibrosa bruno-rossasta separata in profondi solchi longitudinali. Tronco talvolta con costolature; rami orizzontali. Rametti a SEZIONE APPIATTITA. Squame con LINEA BIANCA DI STOMI A FORMA DI Y sulla pagina inferiore. LATERALI PIU'ALTE DELLE CENTRALI. Se stropicciate, le squame odorano di prezzemolo. Stobili più piccoli del genere cupressus ma legnosi"},{"id":"153_variety_x_cupressocyparis","nomeSci":"× Cupressocyparis leylandii","famiglia":"Cupressaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"2","provenienza":"stati uniti occidentali","varieta":null,"isVarieta":true,"pagina":153,"note":"IBRIDO INCROCIO TRA CUPRESSUS MACROCARPA E CHAMAECYPARIS NOOTKATENSIS COLORAZIONE PIU' GRIGIASTRA CHE VERDE. Meno ramificazione; molto usato per creare siepi. Corteccia rossastra con fessurazioni longitudinali Squame di colore verde-grigiastro, in rilievo più o meno pronunciato. Squame più delicate, rametti laterali più lunghi . Strobili SINGOLI LEGNOSI, che a maturità presentano nella parte mediana delle squame un rilievo più o meno pronunciato"},{"id":"154_species_thuja_orientalis","nomeSci":"Thuja orientalis","famiglia":"Cupressaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"2","provenienza":"cina","varieta":null,"isVarieta":false,"pagina":154,"note":"PLATYCLADUS ORIENTALIS Corteccia bruno-rossasta sottile, che si sfalda in fessurazioni longitudinali. Rametti disposti VERTICALMENTE rispetto al piano orizzontale dell'albero. Squame di colore verde scuro su entrambe le facce, ovoidali, inoldore. Stroboli eretti, con APICE APPUNTITO PROMINENTE, Formando un UNCINO, carnosi e glauchi da giovani, si aprono a coppa in età matura"},{"id":"156_species_abies_nordmanniana","nomeSci":"Abies nordmanniana","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"caucaso","varieta":null,"isVarieta":false,"pagina":156,"note":"ABETE DEL CAUCASO Corteccia liscia e sottile nelle piante giovani, grigio- bruna, che si fessura in placche grigie aderenti nei soggetti adulti. Aghi solitari RIVOLTI IN AVANTI, con apice smarginato, scuri sopra e con due STRISCE BIANCO-AZZURRE SOTTO. Giovani rami glabri verdastri. Strobili bruno-scuri coperti da resina con squame sporgenti e punta ricurva verso il basso"},{"id":"157_species_picea_abies","nomeSci":"Picea abies","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"nord europa","varieta":null,"isVarieta":false,"pagina":157,"note":"PICEA EXCELSA - ABETE ROSSO Corteccia bruno-ruggine , liscia nei soggetti giovani, grigio-violacea screpolata in lacche rotondeggianti negli adulti. Ago a sezione quadrangolare; aghi solitari a punta aguzza, disposti intorno al ramo o mancanti sulla parte inferiore, causa torsione dell'ago. Giovani rami bruno -rossicci pendenti. Strobili cilindrici lunghi (10-15 cm) e PENDULI, che cadono interi a maturità"},{"id":"158_species_picea_pungens","nomeSci":"Picea pungens","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"stati uniti, montagne roc.","varieta":null,"isVarieta":false,"pagina":158,"note":"ABETE DEL COLORADO Corteccia bruno-grigiastra A SCAGLIE da adulta. Aghi a sezione quadrangolare, solitari, rigidi e pungenti, GLAUCO-VERDASTRI, inseriti a spazzola sui rametti. Rami giovani glabri di colore giallo-bruno con cuscinetti molto rilevanti. Strobili con squame allungate con punte riflesse"},{"id":"159_variety_picea_pungens","nomeSci":"Picea pungens","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"stati uniti, montagne roc.","varieta":"Koster","isVarieta":true,"pagina":159,"note":"VARIETA' CON AGHI DI COLORE GRIGIO-AZZURRO"},{"id":"161_species_pinus_sylvestris","nomeSci":"Pinus sylvestris","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"europa","varieta":null,"isVarieta":false,"pagina":161,"note":"PINO SILVESTRE. Corteccia rosso ruggine nella porzione più alta (più giovane) del tronco e nei rami apicali, grigio-bruna nella parte basale. Aghi a COPPIE, flessibili, eretti, ritorti, rigidi ed appuntiti, con margini finemente dentati. Giovani getti glauchi, bruno-grigiastri, lisci. Strobili piccoli ovoidali- conici grigiastri"},{"id":"162_variety_pinus_nigra","nomeSci":"Pinus nigra","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"europa","varieta":"Nigra","isVarieta":true,"pagina":162,"note":"PINO AUSTRIACO Corteccia spesso grigia, poi nerastra profondamente screpolata, a placche aderenti. Aghi a coppie molto lunghi, pungenti, disposti a spirale lungo il ramo, di colore verde scuro, rigidi e perpendicolari al ramo. Strobili piccoli conico-ovoidali, bruno chiaro. Gemme resinose ovoidale acute","gemmeForma":"ovoidale"},{"id":"163_variety_pinus_nigra","nomeSci":"Pinus nigra","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"europa meridionale","varieta":"Maritima","isVarieta":true,"pagina":163,"note":"PINO DI CORSICA . Sinonimo Salzmannii var. corsicana. Corteccia a grosse PLACCHE CHIARE che risaltano sulle fessurazioni quasi nere. Aghi più lunghi della varietà 'nigra', leggermente contorti, radi e non disposti a spirale ma SPARSI SUI RAMI"},{"id":"164_species_pinus_pinaster","nomeSci":"Pinus pinaster","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"europa meridionale","varieta":null,"isVarieta":false,"pagina":164,"note":"PINO MARITTIMO. Chioma ad ombrello, non appiattiva ma OVOIDALE. Corteccia spessa di colore bruno-violaceo, profondamente fessurata, fessurazioni interne di colore rosso vino, con placche che si staccano facilmente. Aghi a coppie, rigidi e pungenti, di colore verde scuro, con guaina lunga 2.5 cm. Giovani rami rossastri, squamosi e glabri. Strobili grandi ovoidali/conici, spesso asimmetrici, riuniti a gruppi di due o più intorno. SCAGLIE INF.ERIORI AD UNCINO","chiomaForma":"ad ombrello","gemmeForma":"ovoidale"},{"id":"165_species_pinus_pinea","nomeSci":"Pinus pinea","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"europa meridionale","varieta":null,"isVarieta":false,"pagina":165,"note":"PINO DA PINOLI. Chioma espansa ad OMBRELLO PIATTO. Corteccia grigio-aranciata, con profonde fessure longitudinali, a placche che si sfogliano. Aghi a coppie di colore verde scuro, leggermente contorti con margini finemente dentati, apice acuto e guaina lunga 1 cm. Giovani rami grigio-verdi glabri. Strobili grandi ovidali globulosi, simmetrici","chiomaForma":"a ombrello"},{"id":"167_species_pinus_strobus","nomeSci":"Pinus strobus","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"nord america orientale","varieta":null,"isVarieta":false,"pagina":167,"note":"PINO STROBO. Rami riuniti verticillati, in palchi ben distinti , con portamento ORIZZONTALE molto marcato. Corteccia sottile e liscia nei soggetti giovani, fessurata a placche rettangolari nerastre in età adulta. Aghi a ciuffi di 5, glauchi, molto sottili ma ERETTI E RIGIDI. Giovani rami con sottili peli bruno-arancio. Stobili cilindrici, lunghi 10-15 cm, penduli e leggermente arcuati","ramiInserzione":"verticillati"},{"id":"168_species_pinus_wallichiana","nomeSci":"Pinus wallichiana","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"himalaya","varieta":null,"isVarieta":false,"pagina":168,"note":"PINO ECCELSO. Rami riuniti e verticillati in palchi ben distinti, con portamento ORIZZONTALE, molto marcato. Corteccia grigio-bruna, fessurata superficialmente. Aghi a ciuffi di 5, molto lunghi e flessibili, di colore verde glauco, più lunghi del Pinus strobus e PENDULI. Giovani rami glabri, glauco-verdi. Strobili cilindrici MOLTO LUNGHI, da 10 a 25 cm e resinosi","ramiInserzione":"verticillati"},{"id":"170_variety_cedrus_deodara","nomeSci":"Cedrus deodara","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"himalaya","varieta":null,"isVarieta":true,"pagina":170,"note":"CEDRO DEODARA- CEDRO DELL'HIMALAYA Corteccia scura con piccole squame. GETTI TERMINALI PENDULI (caratteristica fondamentale) Aghi a MAZZETTI LUNGHI e flessibili, color verde chiaro, inseriti su BRACHIBLASTI. Strobili arrotondati, mai incavati all'apice, appuntiti a forma di limone, che si squamano arrivati a maturità"},{"id":"171_variety_cedrus_deodara","nomeSci":"Cedrus deodara","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"3","provenienza":"himalaya","varieta":"Pendula","isVarieta":true,"pagina":171,"note":"VARIETA' CON PORTAMENTO PIANGENTE","chiomaForma":"piangente"},{"id":"172_variety_cedrus_atlantica","nomeSci":"Cedrus atlantica","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"nord africa, catena atl.","varieta":null,"isVarieta":true,"pagina":172,"note":"CEDRO D'ATLANTE. Corteccia scura con squame piccole separate da piccole screpolature. Chioma rada con cima e GIOVANI RAMI ERETTI. Aghi a MAZZETTI più corti della specie Deodara, verde scuro, inseriti su BRACHIBLASTI. Strobili ovoidali nettamente incavati all'apice, che si squamano in età matura"},{"id":"173_variety_cedrus_atlantica","nomeSci":"Cedrus atlantica","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"nord africa, catena a,ì.","varieta":"Glauca","isVarieta":true,"pagina":173,"note":"VARIETA' CON AGHI GRIGIO-VERDI"},{"id":"174_variety_cedrus_atlantica","nomeSci":"Cedrus atlantica","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"nord africa, catena a,ì.","varieta":"Pendula","isVarieta":true,"pagina":174,"note":"VARIETA' CON PORTAMENTO PIANGENTE","chiomaForma":"piangente"},{"id":"175_species_cedrus_libani","nomeSci":"Cedrus libani","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"sempreverde","grandezza":"1","provenienza":"mediterraneo orientale","varieta":null,"isVarieta":false,"pagina":175,"note":"CEDRO DEL LIBANO. Corteccia scura con piccole squame. Chioma denso con cima inclinata ma non pendula. FUSTO POLICORMICO. Rami secondari a candelabro, fittamente ramificati; rametti terminali ERETTI, o leggermente inclinati ma non penduli. Aghi a mazzetti più corti della specie Deodara, verde scuro, inseriti su BRACHIBLASTI. Strobili ovali, troncati all'apice, incavati, che si squamano a maturità raggiunta"},{"id":"176_species_larix_decidua","nomeSci":"Larix decidua","famiglia":"Pinaceae","divisione":"CONIFERE","tipologia":"caducifoglia","grandezza":"1","provenienza":"europa centrale","varieta":null,"isVarieta":false,"pagina":176,"note":"LARICE. ATTENZIONE : CADUCIFOGLIA !!!! Corteccia grigia in placche separate da fessure longitudinali bruno-rossastre. Rami BRACHIBLASTI di colore NERASTRO.; giovani rami grigio-giallastri glabri. Gemme quasi sferiche e resinose; chioma rada di colore verde brillante. Aghi teneri di colore verde chiaro, in ciuffi portati da BRACHIBLASTI. Strobili piccoli ovoidi ed eretti, rimangono sulla pianta per diversi anni"}];
